function UIBattlingSkillCatNode:InitData(record)
    self.id = record.id
    self.catId = record.cId
    self.type = record.t
    self.star = record.s
    self.playerId = record.pId
    self.camp = record.c
    self.finalSkills = record.fs
    self.passiveSkills = record.ps

    local ultraInfo = Tools.splitToNum(self.finalSkills, '=')
    self.skillCardData = {
        skillId = ultraInfo[1],
        star = ultraInfo[2]
    }
    self.skillContext = {
        pos = {
            [1] = -1,
            [2] = -1,
        }
    }
end

function UIBattlingSkillCatNode:InitComponent()
    if self.inited == true then
        return
    end
    self.inited = true
    local roleCat = BattleViewMgr:FindRoleView(self.id)
    self.AImg_Cat:LoadSprite(roleCat.catImgPath)
    UIEventProxy.Create(self.RT_BG.gameObject).onPointerDown = Bind(self, self.ActionOnPointerDown)
    UIEventProxy.Create(self.RT_BG.gameObject).onPointerUp = Bind(self, self.ActionOnPointerUp)

    local showAutoBtn = true
    KTool.SetActive(self.Btn_Auto, showAutoBtn)
    if showAutoBtn then
        SetButtonAction(self.Btn_Auto.gameObject, Bind(self, self.OnAutoBtnClicked))
        self.auto = GameUtils.LoadInt(AutoUseSkillCatKey, 1) == 1
        KTool.SetActive(self.ImgOn, self.auto)
        KTool.SetActive(self.ImgOff, not self.auto)
        Events.Broadcast(Constants.EventNames.BattleInputAutoUseSkillCat, BattleInfo.myPlayerId, self.auto)
    end
end

function UIBattlingSkillCatNode:GetWorldPos()
    return self.RT_BG.position
end

--- 切换可交互状态
---@param state any
function UIBattlingSkillCatNode:SwitchInteractiveState(state)
    self.canInteractive = state
end

--- 刷新UI显示内容
---@param stateInfo any
function UIBattlingSkillCatNode:RefreshState(stateInfo, skipRecord)
    if skipRecord ~= false then
        self.lastStateInfo = stateInfo
    end
    local infos = string.split(stateInfo, "_")
    local curCD = checkInt(infos[3])
    local maxCD = checkInt(infos[4])
    local remainNums = checkInt(infos[5])
    local totalNums = checkInt(infos[6])

    self.Txt_Round.text = tostring(curCD)
    self.Img_Round.fillAmount = curCD / maxCD
    KTool.SetActive(self.Img_Round, true)
    self.canUse = false
    self.remainNum = remainNums
    self.curCD = curCD

    if remainNums > 0 then
        if curCD == 0 then
            self.canUse = true
            self.Anim_FX:Play(AnimOpenFX)
            KTool.SetActive(self.Txt_Round.transform.parent, false)
            KTool.SetActive(self.RT_RemainNum, true)
            self.Txt_RemainNum.text = tostring(remainNums)
        else
            self.Anim_FX:Play(AnimCloseFX)
            KTool.SetActive(self.Txt_Round.transform.parent, true)
            KTool.SetActive(self.RT_RemainNum, false)
        end
        KTool.SetActive(self.RT_TextEnd, false)
    else
        self.Anim_FX:Play(AnimCloseFX)
        self.Img_Round.fillAmount = 1
        KTool.SetActive(self.Txt_Round.transform.parent, false)
        KTool.SetActive(self.RT_TextEnd, true)
        KTool.SetActive(self.RT_RemainNum, false)
    end
end

--- 重新设置成上一次刷新时的状态
function UIBattlingSkillCatNode:ResetState()
    self:RefreshState(self.lastStateInfo)
    -- 主动猫球滚蛋
    BattleViewMgr:FindRoleView(self.id):PlayActiveExit()
end

function UIBattlingSkillCatNode:OnUse()
    -- 主动猫球出现
    BattleViewMgr:FindRoleView(self.id):PlayActiveEnter()
end

--- 设置UI显隐状态
---@param state any
function UIBattlingSkillCatNode:SetShowState(state)
    if state == true then
        self.Anim_FX:Play(AnimShowFXAlpha)  -- 防止漏光用的
        if self.Anim_Root:IsPlaying(AnimGo)
        or self.Anim_Root:IsPlaying(AnimLoop) then
            return
        end
        self.Anim_Root:Play(AnimGo)
        self.Anim_Root:PlayQueued(AnimLoop)
    else
        self.Anim_FX:Play(AnimCloseFXAlpha) -- 防止漏光用的
        if self.Anim_Root:IsPlaying(AnimOut) then
            return
        end
        self.Anim_Root:Play(AnimOut)
    end
end

--- 设置UIBattlingDialog的引用
---@param ref any
function UIBattlingSkillCatNode:SetUIBattlingDialog(ref)
    self.uiBattlingDialog = ref
end

--- 按钮按钮的回调
---@param pointerData any
function UIBattlingSkillCatNode:ActionOnPointerDown(pointerData)
    self.coPress = cs_coroutine.start(function()
        self.interactiveType = InteractiveType.Click
        cs_coroutine.yield_return(WaitForSecondsRealtime(PressTime))
        self.interactiveType = InteractiveType.Press
        self:OnPress()
        self.coPress = nil
    end)
end

--- 按钮抬起的回调
---@param pointerData any
function UIBattlingSkillCatNode:ActionOnPointerUp(pointerData)
    if self.coPress then
        cs_coroutine.stop(self.coPress)
        self.coPress = nil
    end
    if self.interactiveType == InteractiveType.Click then
        self:OnClick()
    elseif self.interactiveType == InteractiveType.Press then
        self:OnPressEnd()
    end
end

--- 长按回调
function UIBattlingSkillCatNode:OnPress()
    -- 显示技能说明
    local RT_CatBallSkillTips = self.uiBattlingDialog.RT_CatBallSkillTipsPanel
    KTool.SetActive(RT_CatBallSkillTips, true)
    local LB_SkillTips = GetLuaBehaviour(RT_CatBallSkillTips.gameObject, "Game.UI.UIBattling.UIBattlingTipsPanel")
    local data = {
        roleId = self.id,
        skillId = self.skillCardData.skillId,
        star = self.skillCardData.star,
        skillLv = 1,
        imgPath = BattleViewMgr:FindRoleView(self.id).catImgPath
    }
    LB_SkillTips.Env:SetPanelInfo(data)
end

function UIBattlingSkillCatNode:OnPressEnd()
    -- 隐藏技能说明
    KTool.SetActive(self.uiBattlingDialog.RT_CatBallSkillTipsPanel, false)
end

--- 按钮点击回调
function UIBattlingSkillCatNode:OnClick()
    if self.canInteractive then
        if self.canUse then
            self.uiBattlingDialog:OnSkillCardClickCommon({skillCardData = self.skillCardData}, self.skillContext)
            -- local newStateInfo = self:CalculateNextStateInfo()
            -- self:RefreshState(newStateInfo, false)
            -- -- 主动猫球出现
            -- BattleViewMgr:FindRoleView(self.id):PlayActiveEnter()
        else
            if self.remainNum <= 0 then
                GameUtils.Toast(localize("猫球本场战斗已无使用次数"))
            elseif self.curCD > 0 then
                GameUtils.Toast(localize("猫球处于CD中"))
            end
        end
    end
end

